pub fn sha256Hex(bytes: []const u8) [64]u8 {
    var digest: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(bytes, &digest, .{});
    return std.fmt.bytesToHex(digest, .lower);
}

pub fn modelWriteIdentity(
    actor: []const u8,
    operation_id: []const u8,
    model_id: []const u8,
    session_token_text: []const u8,
    generation: u64,
) ?model_write_lease.Identity {
    if (generation == 0 or generation > std.math.maxInt(u32)) return null;
    const session_token = std.fmt.parseInt(u32, session_token_text, 10) catch return null;
    if (session_token == 0) return null;
    return .{
        .actor = actor,
        .operation_id = operation_id,
        .model_id = model_id,
        .session_token = session_token,
        .generation = @intCast(generation),
    };
}

pub fn modelWriteIdentityIsResident(identity: model_write_lease.Identity, require_generation: bool) bool {
    return z3d.modelSessionResident() and
        z3d.modelDocumentTokenForId(identity.model_id) == z3d.g_model_session_token and
        identity.session_token == z3d.g_model_session_token and
        (!require_generation or identity.generation == z3d.g_edit_generation);
}

