}

/// Acquire the one writer receipt before any restore allocation or journal edit.
pub fn modelWriteLeaseAcquireJsonAlloc(
    allocator: std.mem.Allocator,
    request_json: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(z3d.ModelWriteIdentityRequestV1, allocator, request_json, .{}) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid model-write lease request", false);
    defer parsed.deinit();
    const request = parsed.value;
    const identity = z3d.modelWriteIdentity(
        request.actor,
        request.operationId,
        request.modelId,
        request.sessionToken,
        request.expectedGeneration,
    ) orelse return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid model-write lease identity", false);
    if (request.version != 1)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid model-write lease version", false);
    if (z3d.g_historical_preview.blocksResidentMutation())
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "lease_refused", "close the active historical preview before mutating the resident model", false);
    if (!z3d.modelSessionResident())
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "no_resident_session", "no resident model document", false);
    if (z3d.modelDocumentTokenForId(identity.model_id) != z3d.g_model_session_token or identity.session_token != z3d.g_model_session_token)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "write lease targets a different resident session", false);
    if (identity.generation != z3d.g_edit_generation)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_generation", "resident mesh generation changed", true);
    const receipt_id = z3d.g_model_write_leases.acquire(identity) catch |err| switch (err) {
        error.LeaseRefused => return z3d.leaseRefusedJsonAlloc(allocator),
        error.InvalidIdentity => return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid model-write lease identity", false),
        error.OutOfMemory => return error.OutOfMemory,
    };
    const response = std.json.Stringify.valueAlloc(allocator, .{
        .ok = true,
        .version = 1,
        .receiptId = receipt_id,
        .modelId = request.modelId,
        .sessionToken = request.sessionToken,
        .generation = z3d.g_edit_generation,
    }, .{}) catch |err| {
        _ = z3d.g_model_write_leases.release(receipt_id) catch {};
        return err;
    };
    return response;
}

/// Validate one guarded field candidate against the exact resident owner while
/// its cold coordinator holds the model write lease. The response contains
/// facts and hashes only; candidate bytes never cross JSON or JavaScript. The
/// cold coordinator independently builds and owns the authoritative bytes from
/// its exact `encodeCurrentAlloc` capture before adoption.
pub fn modelFieldCandidateJsonAlloc(
    allocator: std.mem.Allocator,
    request_json: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(z3d.ModelFieldCandidateRequestV1, allocator, request_json, .{}) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid guarded field-candidate request", false);
    defer parsed.deinit();
    const request = parsed.value;
    if (request.version != 1 or request.leaseReceiptId == 0 or
        request.expectedResidentSha256.len != 64 or request.expectedObjectNamespaceHash.len != 64 or
        !std.mem.eql(u8, request.actor, "field-edit-coordinator"))
    {
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid guarded field-candidate request", false);
    }
    if (z3d.g_historical_preview.blocksResidentMutation())
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "lease_refused", "close the active historical preview before editing resident fields", false);
    const identity = z3d.modelWriteIdentity(
        request.actor,
        request.operationId,
        request.modelId,
        request.sessionToken,
        request.expectedGeneration,
    ) orelse return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid guarded field-candidate identity", false);
    if (!z3d.modelWriteIdentityIsResident(identity, true))
        return if (identity.session_token != z3d.g_model_session_token or z3d.modelDocumentTokenForId(identity.model_id) != z3d.g_model_session_token)
            z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "field candidate targets a different resident session", false)
        else
            z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_generation", "resident mesh generation changed", true);
    z3d.g_model_write_leases.validate(request.leaseReceiptId, identity) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "authorization_failed", "field candidate does not own the active write lease", false);
    const address = z3d.faceAddressView(request.address) orelse
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid guarded authored-face address", false);
    if (address.stability != .stable)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "guarded field edit requires a stable authored-face address", false);

    const resident_bytes = z3d.modelEncodeCurrentDocumentAlloc(allocator, request.modelId) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.WrongModel => return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "resident object namespace belongs to another model", false),
        error.ObjectIdsUnpublished => return z3d.faceRecoveryErrorJsonAlloc(allocator, "object_ids_unpublished", "resident stable object IDs are not published", false),
        else => return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "resident document cannot be encoded exactly", false),
    };
    defer allocator.free(resident_bytes);
    const resident_sha = z3d.sha256Hex(resident_bytes);
    if (!std.mem.eql(u8, &resident_sha, request.expectedResidentSha256))
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_generation", "resident bytes changed after coordinator capture", true);
    var document = meshdoc_format.decodeDocument(allocator, resident_bytes) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "resident document is not canonical RJMD", false);
    defer document.deinit(allocator);
    if (document.version != meshdoc_format.VERSION_LOGICAL_TOPOLOGY or document.range_object_ids == null)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "guarded field edit requires RJMD v5 stable object IDs", false);
    const namespace = meshdoc_format.objectNamespaceDigest(request.modelId, document.range_object_ids.?, document.ranges);
    const namespace_hex = std.fmt.bytesToHex(namespace, .lower);
    if (!std.mem.eql(u8, &namespace_hex, request.expectedObjectNamespaceHash))
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "resident object namespace differs from the guarded face plane", false);

    var candidate = mesh_face_field_candidate.buildAlloc(allocator, .{
        .bytes = resident_bytes,
        .address = address,
        .field = request.field,
        .value = request.value,
    }) catch |err| return z3d.faceRecoveryErrorJsonAlloc(allocator, switch (err) {
        error.StaleAddress => "stale_address",
        error.UnstableAddress, error.AmbiguousAddress => "ambiguous_address",
        error.OutOfMemory => return error.OutOfMemory,
        else => "invalid_request",
    }, @errorName(err), false);
    defer candidate.deinit();
    const candidate_sha = z3d.sha256Hex(candidate.bytes);
    return std.json.Stringify.valueAlloc(allocator, .{
        .ok = true,
        .version = 1,
        .modelId = request.modelId,
        .sessionToken = request.sessionToken,
        .generation = z3d.g_edit_generation,
        .residentSha256 = &resident_sha,
        .candidateSha256 = &candidate_sha,
        .objectNamespaceHash = &namespace_hex,
        .field = candidate.facts.field,
        .before = candidate.facts.before,
        .after = candidate.facts.after,
        .triangleCount = candidate.facts.triangle_count,
    }, .{});
}

/// Release is idempotent for the exact receipt, but a plain finally-release may
/// never silently finalize an unpublished adoption. The coordinator must use the
/// explicit finalize operation only after package, manifest, and plane proof.
pub const ModelDocumentFinalizeReceipt = model_adoption_finalize.Receipt;

/// Allocation-free commit point for a document adoption.  Both receipt
/// registries expose read-only status checks, so every fallible authorization
/// check happens before either registry changes.  Once those checks pass the
/// two mutations cannot allocate and exact retries resolve through the bounded
/// tombstones retained by the registries.
pub fn modelDocumentFinalize(
    lease_receipt_id: u64,
    adoption_receipt_id: u64,
    target_sha256: model_adoption_receipt.HashHex,
) !z3d.ModelDocumentFinalizeReceipt {
    return model_adoption_finalize.commit(
        &z3d.g_model_write_leases,
        &z3d.g_model_adoption_receipts,
        lease_receipt_id,
        adoption_receipt_id,
        target_sha256,
    );
}

pub fn modelWriteLeaseReleaseJsonAlloc(
    allocator: std.mem.Allocator,
    request_json: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(z3d.ModelWriteLeaseReleaseRequestV1, allocator, request_json, .{}) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid model-write lease release", false);
    defer parsed.deinit();
    const request = parsed.value;
    if (request.version != 1 or request.receiptId == 0)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid model-write lease release", false);
    switch (request.operation) {
        .release => {
            if (z3d.g_model_adoption_receipts.active) |adoption| {
                if (adoption.lease_id == request.receiptId)
                    return z3d.faceRecoveryErrorJsonAlloc(allocator, "authorization_failed", "active adoption must be rolled back or explicitly finalized before lease release", false);
            }
            if (request.adoptionReceiptId != null or request.expectedTargetSha256 != null or request.publicationVerified != null)
                return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "plain lease release cannot carry publication proof", false);

            const release_status = z3d.g_model_write_leases.releaseStatus(request.receiptId) catch
                return z3d.faceRecoveryErrorJsonAlloc(allocator, "authorization_failed", "model-write lease receipt is not active", false);
            const response = try std.json.Stringify.valueAlloc(allocator, .{
                .ok = true,
                .version = 1,
                .released = release_status == .released,
                .alreadyReleased = release_status == .already_released,
                .alreadyFinalized = false,
            }, .{});
            errdefer allocator.free(response);
            const released = z3d.g_model_write_leases.release(request.receiptId) catch
                return z3d.faceRecoveryErrorJsonAlloc(allocator, "authorization_failed", "model-write lease release was refused", false);
            std.debug.assert(released == release_status);
            return response;
        },
        .finalize_and_release => {
            if (request.publicationVerified != true or request.adoptionReceiptId == null or
                request.expectedTargetSha256 == null or request.expectedTargetSha256.?.len != 64)
            {
                return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "finalize requires exact adoption and publication proof", false);
            }
            var target_sha256: model_adoption_receipt.HashHex = undefined;
            @memcpy(&target_sha256, request.expectedTargetSha256.?);
            const adoption_status = z3d.g_model_adoption_receipts.finalizeStatus(
                request.adoptionReceiptId.?,
                request.receiptId,
                target_sha256,
            ) catch |err| switch (err) {
                error.WrongTarget => return z3d.faceRecoveryErrorJsonAlloc(allocator, "hash_mismatch", "publication SHA differs from adopted target", false),
                else => return z3d.faceRecoveryErrorJsonAlloc(allocator, "authorization_failed", "adoption receipt is not active for finalization", false),
            };
            const release_status = z3d.g_model_write_leases.releaseStatus(request.receiptId) catch
                return z3d.faceRecoveryErrorJsonAlloc(allocator, "authorization_failed", "model-write lease receipt is not active", false);

            // Reserve the exact response before either receipt changes state.
            // If the caller loses this response, the bounded tombstones make an
            // exact retry return the same successful state.
            const response = try std.json.Stringify.valueAlloc(allocator, .{
                .ok = true,
                .version = 1,
                .released = release_status == .released,
                .alreadyReleased = release_status == .already_released,
                .alreadyFinalized = adoption_status == .already_finalized,
            }, .{});
            errdefer allocator.free(response);
            const finalized = z3d.modelDocumentFinalize(
                request.receiptId,
                request.adoptionReceiptId.?,
                target_sha256,
            ) catch unreachable;
            std.debug.assert(finalized.finalized == (adoption_status == .finalized));
            std.debug.assert(finalized.already_finalized == (adoption_status == .already_finalized));
            std.debug.assert(finalized.released == (release_status == .released));
            std.debug.assert(finalized.already_released == (release_status == .already_released));
            return response;
        },
    }
}

pub fn rollbackAdoptedJournalAction(
    adoption: model_adoption_receipt.Receipt,
    target_snapshot: *z3d.JournalEntry,
) bool {
    if (z3d.g_journal_undo.items.len == 0) return false;
    const top_index = z3d.g_journal_undo.items.len - 1;
    if (z3d.g_journal_undo.items[top_index].action_id != adoption.action_id) return false;
    var preimage = z3d.g_journal_undo.items[top_index];
    z3d.g_journal_undo.items.len = top_index;
    const restored = z3d.journalInstall(&preimage) and z3d.journalResidentDurableMatches(&preimage);
    if (!restored) {
        const target_restored = z3d.journalInstall(target_snapshot) and z3d.journalResidentDurableMatches(target_snapshot);
        if (!target_restored)
            std.log.err("[model-recovery] adoption rollback and target reinstatement both failed verification", .{});
        z3d.g_journal_undo.appendAssumeCapacity(preimage);
        return false;
    }
    const encoded = z3d.modelEncodeCurrentDocumentAlloc(z3d.jalloc, preimage.part_object_model_id orelse "") catch {
        _ = z3d.journalInstall(target_snapshot);
        z3d.g_journal_undo.appendAssumeCapacity(preimage);
        return false;
    };
    defer z3d.jalloc.free(encoded);
    const restored_sha = z3d.sha256Hex(encoded);
    if (!std.mem.eql(u8, &restored_sha, &adoption.preimage_sha256)) {
        _ = z3d.journalInstall(target_snapshot);
        z3d.g_journal_undo.appendAssumeCapacity(preimage);
        return false;
    }
    if (preimage.action_kind) |kind| z3d.enqueueMeshAction(
        preimage.action_id,
        kind,
        .undone,
        target_snapshot.count,
        preimage.count,
        z3d.partCountFromRanges(target_snapshot.part_ranges),
        z3d.partCountFromRanges(preimage.part_ranges),
    );
    z3d.enqueueFollowJournalAction(
        preimage.action_id,
        if (preimage.action_kind) |kind| @intFromEnum(kind) else 255,
        .undone,
        preimage.label,
        target_snapshot.count,
        preimage.count,
        z3d.partCountFromRanges(target_snapshot.part_ranges),
        z3d.partCountFromRanges(preimage.part_ranges),
    );
    z3d.journalFreeEntry(&preimage);
    z3d.journalFreeStack(&z3d.g_journal_redo);
    z3d.armIntegrityRollCall("historical restore rollback");
    return true;
}

/// Adopt caller-borrowed, capability-verified RJMD bytes as one exact journal
/// action. Decode and every target allocation complete before resident mutation.
pub fn modelDocumentAdoptBytesJsonAlloc(
    allocator: std.mem.Allocator,
    request_json: []const u8,
    bytes: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(z3d.ModelDocumentAdoptRequestV1, allocator, request_json, .{}) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid document-adopt request", false);
    defer parsed.deinit();
    const request = parsed.value;
    if (request.version != 1 or request.leaseReceiptId == 0 or request.expectedSha256.len != 64)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid document-adopt request", false);
    const identity = z3d.modelWriteIdentity(
        request.actor,
        request.operationId,
        request.modelId,
        request.sessionToken,
        request.expectedGeneration,
    ) orelse return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid document-adopt identity", false);
    if (!z3d.modelWriteIdentityIsResident(identity, true))
        return if (identity.session_token != z3d.g_model_session_token or z3d.modelDocumentTokenForId(identity.model_id) != z3d.g_model_session_token)
            z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "document adopt targets a different resident session", false)
        else
            z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_generation", "resident mesh generation changed", true);
    z3d.g_model_write_leases.validate(request.leaseReceiptId, identity) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "authorization_failed", "document adopt does not own the active write lease", false);
    const journal_label: []const u8 = switch (request.journalKind) {
        .historical_restore => if (std.mem.eql(u8, request.actor, "recovery-coordinator"))
            "historical restore"
        else
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "historical restore adoption requires the recovery coordinator", false),
        .field_edit => if (std.mem.eql(u8, request.actor, "field-edit-coordinator"))
            "guarded field edit"
        else
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "field-edit adoption requires the field-edit coordinator", false),
    };
    if (z3d.g_model_adoption_receipts.active != null)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "lease_refused", "the active write lease already owns an adoption", false);

    const target_sha = z3d.sha256Hex(bytes);
    if (!std.mem.eql(u8, &target_sha, request.expectedSha256))
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "hash_mismatch", "candidate bytes differ from expected SHA-256", false);
    var document = meshdoc_format.decodeDocument(allocator, bytes) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "candidate is not a readable current RJMD document", false);
    defer document.deinit(allocator);
    if (document.version != meshdoc_format.VERSION_LOGICAL_TOPOLOGY or document.range_object_ids == null)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "restore candidate must be RJMD v5 with stable object IDs", false);
    var target = z3d.journalEntryFromDocument(&document, request.modelId, journal_label) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "restore candidate channels are incomplete", false),
    };
    defer z3d.journalFreeEntry(&target);

    const preimage_bytes = z3d.modelEncodeCurrentDocumentAlloc(allocator, request.modelId) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.WrongModel => return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "resident object namespace belongs to another model", false),
        error.ObjectIdsUnpublished => return z3d.faceRecoveryErrorJsonAlloc(allocator, "object_ids_unpublished", "resident stable object IDs are not published", false),
        else => return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "resident document cannot be encoded exactly", false),
    };
    defer allocator.free(preimage_bytes);
    const preimage_sha = z3d.sha256Hex(preimage_bytes);

    z3d.g_authorized_model_write_receipt = request.leaseReceiptId;
    defer z3d.g_authorized_model_write_receipt = 0;
    var preimage = z3d.journalSnapshotCurrent(journal_label) orelse
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "could not capture exact resident preimage", false);
    var preimage_live = true;
    defer if (preimage_live) z3d.journalFreeEntry(&preimage);

    if (!z3d.journalInstall(&target) or !z3d.journalResidentDurableMatches(&target)) {
        const rolled_back = z3d.journalInstall(&preimage) and z3d.journalResidentDurableMatches(&preimage);
        return z3d.faceRecoveryErrorJsonAlloc(
            allocator,
            "internal_error",
            if (rolled_back) "candidate adoption was refused and resident preimage was restored" else "candidate adoption and resident rollback both failed",
            false,
        );
    }
    const resident_bytes = z3d.modelEncodeCurrentDocumentAlloc(allocator, request.modelId) catch {
        _ = z3d.journalInstall(&preimage);
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "adopted resident could not be re-encoded", false);
    };
    defer allocator.free(resident_bytes);
    const resident_sha = z3d.sha256Hex(resident_bytes);
    if (!std.mem.eql(u8, &resident_sha, &target_sha)) {
        const rolled_back = z3d.journalInstall(&preimage) and z3d.journalResidentDurableMatches(&preimage);
        return z3d.faceRecoveryErrorJsonAlloc(
            allocator,
            "hash_mismatch",
            if (rolled_back) "adopted resident bytes differ from candidate; preimage restored" else "adopted bytes differ and resident rollback failed",
            false,
        );
    }

    var preimage_optional: ?z3d.JournalEntry = preimage;
    preimage_live = false;
    z3d.journalCommit(&preimage_optional);
    if (preimage_optional != null or z3d.g_last_committed_action_id == 0)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "historical restore could not enter the native journal", false);
    const adoption = z3d.g_model_adoption_receipts.issue(
        request.leaseReceiptId,
        z3d.g_last_committed_action_id,
        z3d.g_model_session_token,
        z3d.g_edit_generation,
        preimage_sha,
        target_sha,
    ) catch {
        var current_target = z3d.journalSnapshotCurrent(journal_label) orelse
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "adoption receipt failed after journal commit", false);
        defer z3d.journalFreeEntry(&current_target);
        const synthetic = model_adoption_receipt.Receipt{
            .id = 0,
            .lease_id = request.leaseReceiptId,
            .action_id = z3d.g_last_committed_action_id,
            .session_token = z3d.g_model_session_token,
            .generation_after = z3d.g_edit_generation,
            .preimage_sha256 = preimage_sha,
            .target_sha256 = target_sha,
        };
        _ = z3d.rollbackAdoptedJournalAction(synthetic, &current_target);
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "adoption receipt registry refused the journal action", false);
    };
    return std.json.Stringify.valueAlloc(allocator, .{
        .ok = true,
        .version = 1,
        .adoptionReceiptId = adoption.id,
        .journalActionId = adoption.action_id,
        .preimageSha256 = &preimage_sha,
        .targetSha256 = &target_sha,
        .residentSha256 = &resident_sha,
        .generation = z3d.g_edit_generation,
        .journalActionKind = @tagName(request.journalKind),
    }, .{}) catch |err| {
        // The caller cannot roll back an adoption whose receipt never crossed
        // the boundary. Treat response allocation as part of the transaction.
        const rolled_back = z3d.rollbackAdoptedJournalAction(adoption, &target);
        if (rolled_back) {
            _ = z3d.g_model_adoption_receipts.consumeRollback(adoption.id, request.leaseReceiptId) catch {};
        } else {
            std.log.err("[model-recovery] response allocation failed and adoption rollback could not verify", .{});
        }
        return err;
    };
}

/// Roll back one adoption exactly once while its original write lease remains
/// active. The target is captured first so a late preimage failure can restore
/// the target plane before this function returns a refusal.
pub fn modelDocumentRollbackJsonAlloc(
    allocator: std.mem.Allocator,
    request_json: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(z3d.ModelDocumentRollbackRequestV1, allocator, request_json, .{}) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid document-rollback request", false);
    defer parsed.deinit();
    const request = parsed.value;
    if (request.version != 1 or request.leaseReceiptId == 0 or request.adoptionReceiptId == 0)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid document-rollback request", false);
    const identity = z3d.modelWriteIdentity(
        request.actor,
        request.operationId,
        request.modelId,
        request.sessionToken,
        request.leaseGeneration,
    ) orelse return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid document-rollback identity", false);
    if (!z3d.modelWriteIdentityIsResident(identity, false))
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "document rollback targets a different resident session", false);
    z3d.g_model_write_leases.validate(request.leaseReceiptId, identity) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "authorization_failed", "document rollback does not own the active write lease", false);
    const adoption = z3d.g_model_adoption_receipts.get(request.adoptionReceiptId, request.leaseReceiptId) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "authorization_failed", "adoption receipt is not active for this lease", false);
    if (request.expectedCurrentGeneration != z3d.g_edit_generation or adoption.generation_after != z3d.g_edit_generation)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_generation", "resident generation changed after adoption", true);
    const target_bytes = z3d.modelEncodeCurrentDocumentAlloc(allocator, request.modelId) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "current adopted resident cannot be encoded", false);
    defer allocator.free(target_bytes);
    const target_sha = z3d.sha256Hex(target_bytes);
    if (!std.mem.eql(u8, &target_sha, &adoption.target_sha256))
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "hash_mismatch", "resident changed after adoption", false);

    z3d.g_authorized_model_write_receipt = request.leaseReceiptId;
    defer z3d.g_authorized_model_write_receipt = 0;
    var target_snapshot = z3d.journalSnapshotCurrent("historical restore") orelse
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "could not retain adopted target for rollback", false);
    defer z3d.journalFreeEntry(&target_snapshot);
    if (!z3d.rollbackAdoptedJournalAction(adoption, &target_snapshot))
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "exact adoption rollback could not be verified", false);
    _ = z3d.g_model_adoption_receipts.consumeRollback(request.adoptionReceiptId, request.leaseReceiptId) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "rollback receipt could not be consumed", false);
    return std.json.Stringify.valueAlloc(allocator, .{
        .ok = true,
        .version = 1,
        .rolledBack = true,
        .adoptionReceiptId = request.adoptionReceiptId,
        .residentSha256 = &adoption.preimage_sha256,
        .generation = z3d.g_edit_generation,
    }, .{});
}

pub const HistoricalPreviewDegradationWireV1 = mesh_face_table.RecoveryDegradationWireV1;

pub const HistoricalPreviewOpenRequestV1 = struct {
    version: u32,
    operation: enum { open },
    modelId: []const u8,
    snapshotId: []const u8,
    resolvedRevision: []const u8,
    expectedSha256: []const u8,
    identityQuality: mesh_face_table.IdentityQuality,
    objectNamespaceHash: []const u8,
    recoveryDegradations: []const z3d.HistoricalPreviewDegradationWireV1,
};

pub const HistoricalPreviewReleaseRequestV1 = struct {
    version: u32,
    operation: enum { release },
    previewToken: []const u8,
};

pub fn historicalPreviewDegradationsAlloc(
    allocator: std.mem.Allocator,
    source: []const z3d.HistoricalPreviewDegradationWireV1,
) ![]mesh_face_table.RecoveryDegradation {
    const result = try allocator.alloc(mesh_face_table.RecoveryDegradation, source.len);
    for (source, result) |row, *target| {
        var actions: std.EnumSet(mesh_face_table.RecoveryDegradationAction) = .empty;
        for (row.actions) |action| actions.insert(action);
        var reasons: std.EnumSet(mesh_face_table.RecoveryDegradationReason) = .empty;
        for (row.reasons) |reason| reasons.insert(reason);
        if (row.actions.len == 0 or row.reasons.len == 0) return error.InvalidRecoveryProvenance;
        target.* = .{
            .channel = row.channel,
            .actions = actions,
            .reasons = reasons,
            .affected_count = row.affectedCount,
        };
    }
    return result;
}

pub fn historicalPreviewOpenJsonAlloc(
    allocator: std.mem.Allocator,
    request_json: []const u8,
    bytes: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(z3d.HistoricalPreviewOpenRequestV1, allocator, request_json, .{}) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid historical preview open request", false);
    defer parsed.deinit();
    const request = parsed.value;
    if (request.version != 1 or request.modelId.len == 0 or request.snapshotId.len == 0 or
        request.resolvedRevision.len != 64 or request.expectedSha256.len != 64 or
        request.objectNamespaceHash.len != 64 or
        (request.identityQuality == .exact) != (request.recoveryDegradations.len == 0))
    {
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid historical preview open request", false);
    }
    // The Lore capability proves the bytes, not which model is currently in
    // this Scene3D owner. Refuse before decoding/parking anything when a stale
    // Versions row from model A is invoked after the viewport moved to model B.
    if (!historical_preview.targetsResident(
        z3d.modelDocumentTokenForId(request.modelId),
        z3d.g_model_session_token,
        z3d.modelSessionResident(),
    ))
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "historical preview does not target the resident Scene3D model", false);
    if (z3d.g_gizmo_snap != null or z3d.g_paint_session or z3d.g_lc != null or z3d.g_bevel != null or z3d.g_quadify != null or
        z3d.g_model_write_leases.owner() != null)
    {
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "lease_refused", "finish the active resident edit before opening historical preview", false);
    }
    const degradations = z3d.historicalPreviewDegradationsAlloc(allocator, request.recoveryDegradations) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid historical preview recovery provenance", false);
    defer allocator.free(degradations);
    const token = z3d.g_historical_preview.open(.{
        .model_id = request.modelId,
        .snapshot_id = request.snapshotId,
        .revision = request.resolvedRevision,
        .sha256 = request.expectedSha256,
        .bytes = bytes,
        .identity_quality = request.identityQuality,
        .recovery_degradations = degradations,
        .max_vertices = z3d.MAX_DYN_VERTS,
    }) catch |err| return z3d.faceRecoveryErrorJsonAlloc(allocator, switch (err) {
        error.PreviewHashMismatch => "hash_mismatch",
        error.PreviewAlreadyOpen => "invalid_request",
        error.PreviewTooLarge => "invalid_request",
        else => "internal_error",
    }, @errorName(err), false);
    defer allocator.free(token);
    z3d.g_historical_preview_saved_orbit = z3d.g_orbit;
    const specimen = &z3d.g_historical_preview.active.?;
    z3d.orbitFrame(specimen.center, specimen.radius);
    errdefer {
        _ = z3d.g_historical_preview.release(token) catch {};
        if (z3d.g_historical_preview_saved_orbit) |saved| z3d.g_orbit = saved;
        z3d.g_historical_preview_saved_orbit = null;
    }
    return std.json.Stringify.valueAlloc(allocator, .{
        .ok = true,
        .version = 1,
        .previewToken = token,
        .modelId = specimen.model_id,
        .snapshotId = specimen.snapshot_id,
        .resolvedRevision = specimen.revision,
        .sha256 = &specimen.sha256,
        .formatVersion = specimen.document.version,
        .triangleCount = specimen.document.verts.len / 24,
        .readOnly = true,
    }, .{});
}

pub fn historicalPreviewReleaseJsonAlloc(
    allocator: std.mem.Allocator,
    request_json: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(z3d.HistoricalPreviewReleaseRequestV1, allocator, request_json, .{}) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid historical preview release request", false);
    defer parsed.deinit();
    if (parsed.value.version != 1 or parsed.value.previewToken.len == 0)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid historical preview release request", false);
    const released = z3d.g_historical_preview.release(parsed.value.previewToken) catch |err|
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "released_capability", @errorName(err), false);
    if (released.released) {
        if (z3d.g_historical_preview_saved_orbit) |saved| z3d.g_orbit = saved;
        z3d.g_historical_preview_saved_orbit = null;
    }
    return std.json.Stringify.valueAlloc(allocator, .{
        .ok = true,
        .version = 1,
        .released = released.released,
        .alreadyReleased = released.already_released,
    }, .{});
}

pub fn historicalPreviewActive() bool {
    return z3d.g_historical_preview.active != null;
}

