    limit: u32,
};

pub const FacePlaneKind = enum { resident, preview };

pub fn facePlaneKind(plane: z3d.FacePlaneRequestV1) ?z3d.FacePlaneKind {
    if (std.mem.eql(u8, plane.source, "resident")) {
        if (plane.sessionToken == null or plane.sessionToken.?.len == 0 or
            plane.expectedGeneration == null or plane.previewToken != null or plane.expectedSha256 != null) return null;
        return .resident;
    }
    if (std.mem.eql(u8, plane.source, "preview")) {
        if (plane.previewToken == null or plane.previewToken.?.len == 0 or
            plane.expectedSha256 == null or plane.expectedSha256.?.len == 0 or
            plane.sessionToken != null or plane.expectedGeneration != null) return null;
        return .preview;
    }
    return null;
}

pub fn faceAddressView(address: z3d.FaceAddressRequestV1) ?mesh_face_table.AddressView {
    if (address.objectId.len == 0) return null;
    if (std.mem.eql(u8, address.stability, "stable")) {
        if (address.artifactFaceOrdinal != null or address.group == indexed_edit_mesh.NO_GROUP) return null;
        return .{
            .object_id = address.objectId,
            .group = address.group,
            .stability = .stable,
        };
    }
    if (std.mem.eql(u8, address.stability, "artifact_rank")) {
        return .{
            .object_id = address.objectId,
            .group = address.group,
            .stability = .artifact_rank,
            .artifact_face_ordinal = address.artifactFaceOrdinal orelse return null,
        };
    }
    return null;
}

pub fn modelDocumentTokenForId(model_id: []const u8) u32 {
    var hash: u32 = 0x811c9dc5;
    for (model_id) |byte| hash = (hash ^ byte) *% 0x01000193;
    return (hash & 0x7fff_ffff) | @as(u32, @intFromBool((hash & 0x7fff_ffff) == 0));
}

pub fn faceSessionTokenMatches(text: []const u8) bool {
    const token = std.fmt.parseInt(u32, text, 10) catch return false;
    return token == z3d.g_model_session_token;
}

pub fn faceSessionTokenText(buffer: []u8) ?[]const u8 {
    return std.fmt.bufPrint(buffer, "{d}", .{z3d.g_model_session_token}) catch null;
}

pub fn faceRecoveryErrorJsonAlloc(
    allocator: std.mem.Allocator,
    code: []const u8,
    detail: []const u8,
    include_generation: bool,
) ![]u8 {
    if (include_generation) return std.json.Stringify.valueAlloc(allocator, .{
        .ok = false,
        .version = 1,
        .code = code,
        .detail = detail,
        .currentGeneration = z3d.g_edit_generation,
    }, .{});
    return std.json.Stringify.valueAlloc(allocator, .{
        .ok = false,
        .version = 1,
        .code = code,
        .detail = detail,
    }, .{});
}

pub fn objectNamespaceHash(model_id: []const u8, object_ids: []const []const u8, ranges: []const u32) [64]u8 {
    return meshdoc_format.objectNamespaceHashHex(model_id, object_ids, ranges);
}

/// Exact resident identity used before every face inspection and recovery
/// capture. The model id is verified against the active document token; a
/// caller cannot claim whichever model happens to be visible.
pub fn meshSessionIdentityJsonAlloc(allocator: std.mem.Allocator, request_json: []const u8) ![]u8 {
    var parsed = std.json.parseFromSlice(z3d.FaceSessionIdentityRequestV1, allocator, request_json, .{}) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid mesh session identity request", false);
    defer parsed.deinit();
    if (parsed.value.version != 1 or parsed.value.modelId.len == 0)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid mesh session identity request", false);
    if (!z3d.modelSessionResident())
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "no_resident_session", "no resident model document", false);
    if (z3d.modelDocumentTokenForId(parsed.value.modelId) != z3d.g_model_session_token)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "the requested model does not own the resident session", false);
    var token_buffer: [16]u8 = undefined;
    const token = z3d.faceSessionTokenText(&token_buffer) orelse
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "could not encode resident session token", false);
    const empty_ids = [_][]const u8{};
    const namespace = z3d.objectNamespaceHash(parsed.value.modelId, &empty_ids, &.{});
    return mesh_face_table.exactSessionIdentityJsonAlloc(
        allocator,
        parsed.value.modelId,
        token,
        z3d.g_edit_generation,
        &namespace,
    );
}

/// Publish stable object identity for the current range table. Any later range
/// mutation clears this publication in model_source; callers must republish the
/// new exact order before a durable face address can be returned.
pub fn meshPublishObjectIdsJsonAlloc(allocator: std.mem.Allocator, request_json: []const u8) ![]u8 {
    if (!z3d.residentMutationAllowed(.durable_channels))
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "historical preview is read-only; object-id publication is blocked", false);
    var parsed = std.json.parseFromSlice(z3d.FaceObjectPublicationV1, allocator, request_json, .{}) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid object-id publication request", false);
    defer parsed.deinit();
    const request = parsed.value;
    if (request.version != 1 or request.modelId.len == 0 or request.sessionToken.len == 0 or request.ranges.len == 0)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid object-id publication request", false);
    if (!z3d.modelSessionResident())
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "no_resident_session", "no resident model document", false);
    if (z3d.modelDocumentTokenForId(request.modelId) != z3d.g_model_session_token or !z3d.faceSessionTokenMatches(request.sessionToken))
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "object ids target a different resident session", false);
    if (request.expectedGeneration != z3d.g_edit_generation)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_generation", "resident mesh generation changed", true);
    const part_ranges = model_source.partRanges() orelse
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "object_ids_unpublished", "resident mesh has no exact part-range table", false);
    if (part_ranges.len != request.ranges.len * 2)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "object_ids_unpublished", "object-id count differs from the resident part-range count", false);
    const object_ids = try allocator.alloc([]const u8, request.ranges.len);
    defer allocator.free(object_ids);
    for (request.ranges, 0..) |row, index| {
        if (row.rank != index or row.objectId.len == 0)
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "object ids must be unique and range-ranked", false);
        for (request.ranges[0..index]) |prior| if (std.mem.eql(u8, prior.objectId, row.objectId))
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "object ids must be unique and range-ranked", false);
        object_ids[index] = row.objectId;
    }
    switch (model_source.publishPartObjectIds(request.modelId, object_ids)) {
        .rejected => return z3d.faceRecoveryErrorJsonAlloc(allocator, "object_ids_unpublished", "native object-id publication was refused", false),
        .unchanged => {},
        .changed => z3d.g_face_table_worker.invalidateIdentity(),
    }
    const namespace = z3d.objectNamespaceHash(request.modelId, object_ids, part_ranges);
    return std.json.Stringify.valueAlloc(allocator, .{
        .ok = true,
        .version = 1,
        .modelId = request.modelId,
        .sessionToken = request.sessionToken,
        .generation = z3d.g_edit_generation,
        .objectCount = object_ids.len,
        .identityQuality = "exact",
        .objectNamespaceHash = &namespace,
        .recoveryDegradations = mesh_face_table.EMPTY_RECOVERY_DEGRADATIONS_V1,
    }, .{});
}

pub fn semanticRegionName(root: std.json.Value, region_id: u32) ?[]const u8 {
    const object = switch (root) {
        .object => |value| value,
        else => return null,
    };
    const regions = switch (object.get("regions") orelse return null) {
        .array => |value| value.items,
        else => return null,
    };
    for (regions) |region| {
        const row = switch (region) {
            .object => |value| value,
            else => continue,
        };
        const id: u32 = switch (row.get("id") orelse continue) {
            .integer => |value| if (value >= 0 and value <= std.math.maxInt(u32)) @intCast(value) else continue,
            else => continue,
        };
        if (id != region_id) continue;
        return switch (row.get("name") orelse return null) {
            .string => |value| if (value.len > 0) value else null,
            else => null,
        };
    }
    return null;
}

pub fn residentFaceAnalysisJobAlloc(
    allocator: std.mem.Allocator,
    model_id: []const u8,
    session_token: []const u8,
) !mesh_face_table_worker.PreparedJob {
    if (!z3d.ensureIndexedEditMesh()) return error.NoResidentMesh;
    const mesh = if (z3d.g_indexed_edit_mesh) |*resident| resident else return error.NoResidentMesh;
    const published_model = model_source.partObjectModelId() orelse return error.ObjectIdsUnpublished;
    if (!std.mem.eql(u8, published_model, model_id)) return error.WrongModel;
    const ids_json = model_source.partObjectIdsJson() orelse return error.ObjectIdsUnpublished;
    const ranges = model_source.partRanges() orelse return error.ObjectIdsUnpublished;

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const temp = arena.allocator();
    var parsed_ids = try std.json.parseFromSlice(std.json.Value, temp, ids_json, .{});
    defer parsed_ids.deinit();
    const id_values = switch (parsed_ids.value) {
        .array => |value| value.items,
        else => return error.ObjectIdsUnpublished,
    };
    if (id_values.len == 0 or id_values.len * 2 != ranges.len) return error.ObjectIdsUnpublished;
    const object_ids = try temp.alloc([]const u8, id_values.len);
    const bindings = try temp.alloc(mesh_face_table.ObjectBinding, id_values.len);
    for (id_values, 0..) |value, index| {
        const object_id = switch (value) {
            .string => |text| if (text.len > 0) text else return error.ObjectIdsUnpublished,
            else => return error.ObjectIdsUnpublished,
        };
        object_ids[index] = object_id;
        bindings[index] = .{ .rank = @intCast(index), .object_id = object_id };
    }

    var parsed_semantics: ?std.json.Parsed(std.json.Value) = null;
    defer if (parsed_semantics) |*value| value.deinit();
    if (model_source.semanticTableJson()) |json| {
        parsed_semantics = std.json.parseFromSlice(std.json.Value, temp, json, .{}) catch null;
    }
    var labels = std.ArrayListUnmanaged(mesh_face_table.DurableFaceLabelInput).empty;
    defer labels.deinit(temp);
    if (parsed_semantics) |parsed| for (mesh.faces.items) |*face| {
        if (!face.alive) continue;
        const name = z3d.semanticRegionName(parsed.value, face.semantic.region) orelse continue;
        try labels.append(temp, .{
            .face_id = face.id,
            .face_name = name,
            .semantic_region_name = name,
        });
    };

    const render_classes = try temp.alloc(mesh_face_table.RenderClass, mesh.faces.items.len);
    @memset(render_classes, .@"opaque");
    for (mesh.faces.items) |*face| {
        if (!face.alive or face.id >= render_classes.len) continue;
        for (face.source_triangles.items) |triangle| {
            const color = model_source.colorOf(triangle) orelse continue;
            if (model_paint.isGlassAlpha(color[3])) {
                render_classes[face.id] = .glass;
                break;
            }
        }
    }
    const namespace = z3d.objectNamespaceHash(model_id, object_ids, ranges);
    return mesh_face_table_worker.PreparedJob.captureIndexedAlloc(allocator, .{
        .mesh = mesh,
        .identity = .{
            .source = .resident,
            .model_id = model_id,
            .session_token = session_token,
            .generation = z3d.g_edit_generation,
            .identity_quality = .exact,
            .object_namespace_hash = &namespace,
        },
        .object_bindings = bindings,
        .durable_labels = labels.items,
        .render_class_by_face = render_classes,
    });
}

pub fn residentFacePlaneHashAlloc(
    allocator: std.mem.Allocator,
    model_id: []const u8,
    session_token: []const u8,
) ![64]u8 {
    const published_model = model_source.partObjectModelId() orelse return error.ObjectIdsUnpublished;
    if (!std.mem.eql(u8, published_model, model_id)) return error.WrongModel;
    const ids_json = model_source.partObjectIdsJson() orelse return error.ObjectIdsUnpublished;
    const ranges = model_source.partRanges() orelse return error.ObjectIdsUnpublished;
    var parsed_ids = try std.json.parseFromSlice(std.json.Value, allocator, ids_json, .{});
    defer parsed_ids.deinit();
    const values = switch (parsed_ids.value) {
        .array => |value| value.items,
        else => return error.ObjectIdsUnpublished,
    };
    if (values.len == 0 or values.len * 2 != ranges.len) return error.ObjectIdsUnpublished;
    const object_ids = try allocator.alloc([]const u8, values.len);
    defer allocator.free(object_ids);
    for (values, 0..) |value, index| object_ids[index] = switch (value) {
        .string => |text| if (text.len > 0) text else return error.ObjectIdsUnpublished,
        else => return error.ObjectIdsUnpublished,
    };
    const namespace = z3d.objectNamespaceHash(model_id, object_ids, ranges);
    return mesh_face_table_worker.planeIdentityHash(.{
        .source = .resident,
        .model_id = model_id,
        .session_token = session_token,
        .generation = z3d.g_edit_generation,
        .identity_quality = .exact,
        .object_namespace_hash = &namespace,
    });
}

pub const ResidentAnalysisLookup = union(enum) {
    snapshot: *const mesh_face_table.FaceAnalysisSnapshot,
    response: []u8,
};

pub fn residentAnalysisErrorAlloc(
    allocator: std.mem.Allocator,
    err: anyerror,
) ![]u8 {
    return switch (err) {
        error.ObjectIdsUnpublished => z3d.faceRecoveryErrorJsonAlloc(allocator, "object_ids_unpublished", "stable resident object ids have not been published", false),
        error.WrongModel => z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "published object ids belong to a different model", false),
        error.NoResidentMesh => z3d.faceRecoveryErrorJsonAlloc(allocator, "no_resident_session", "resident mesh has no editable topology", false),
        else => z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "resident face analysis capture failed", false),
    };
}

pub fn residentFaceAnalysisLookup(
    io: std.Io,
    allocator: std.mem.Allocator,
    model_id: []const u8,
    session_token: []const u8,
) !z3d.ResidentAnalysisLookup {
    if (!z3d.g_face_table_worker.isStarted()) {
        z3d.g_face_table_worker.start(io, allocator, 2) catch
            return .{ .response = try z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "resident face-analysis worker could not start", false) };
    }
    const identity_hash = z3d.residentFacePlaneHashAlloc(allocator, model_id, session_token) catch |err|
        return .{ .response = try z3d.residentAnalysisErrorAlloc(allocator, err) };
    if (z3d.g_face_table_worker.cacheView(io, identity_hash)) |cached| switch (cached) {
        .success => |snapshot| {
            _ = z3d.g_face_table_worker.selectCached(io, identity_hash);
            return .{ .snapshot = snapshot };
        },
        .diff => return .{ .response = try z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "resident face cache contains an invalid result kind", false) },
        .failure => |failure| return .{ .response = try z3d.faceRecoveryErrorJsonAlloc(
            allocator,
            @tagName(mesh_face_table_worker.publicFailureCode(.resident, failure.code)),
            failure.text(),
            false,
        ) },
    };
    if (z3d.g_face_table_worker.pendingReceipt(io, identity_hash)) |receipt|
        return .{ .response = try mesh_face_table_worker.pendingJsonAlloc(allocator, receipt) };

    var prepared = z3d.residentFaceAnalysisJobAlloc(allocator, model_id, session_token) catch |err|
        return .{ .response = try z3d.residentAnalysisErrorAlloc(allocator, err) };
    if (!std.mem.eql(u8, &prepared.identityHash(), &identity_hash)) {
        prepared.deinit();
        return .{ .response = try z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "resident capture identity changed during owner copy", false) };
    }
    return switch (z3d.g_face_table_worker.submitOwned(io, prepared)) {
        .queued => |receipt| .{ .response = try mesh_face_table_worker.pendingJsonAlloc(allocator, receipt) },
        .stopped => .{ .response = try z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "resident face-analysis worker stopped", false) },
    };
}

pub fn faceRequestIsDiff(allocator: std.mem.Allocator, request_json: []const u8) bool {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, request_json, .{}) catch return false;
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |object| object,
        else => return false,
    };
    const source = switch (root.get("source") orelse return false) {
        .string => |value| value,
        else => return false,
    };
    return std.mem.eql(u8, source, "diff");
}

pub fn diffQueryErrorJsonAlloc(
    allocator: std.mem.Allocator,
    err: mesh_face_diff.DiffError,
) ![]u8 {
    return switch (err) {
        error.OutOfMemory => error.OutOfMemory,
        error.InvalidQuery => z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-diff query", false),
        error.AuditUnavailable => z3d.faceRecoveryErrorJsonAlloc(allocator, "audit_unavailable", "requested diff audit facts were not computed", false),
        error.StaleCursor => z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_cursor", "face-diff cursor belongs to another plane or query", false),
        error.AddressNotInQuery => z3d.faceRecoveryErrorJsonAlloc(allocator, "address_not_in_query", "face address is not present in this diff query", false),
        error.InvalidPlanes, error.InvalidReceipt => z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "native face-diff planes are inconsistent", false),
    };
}

pub fn meshFaceDiffJsonAlloc(
    io: std.Io,
    allocator: std.mem.Allocator,
    request_json: []const u8,
) ![]u8 {
    var parsed = mesh_face_diff.parseRequestAlloc(allocator, request_json) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-diff v1 request", false),
    };
    defer parsed.deinit();
    const resident_query = parsed.resident.query;
    if (!z3d.modelSessionResident())
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "no_resident_session", "no resident model document", false);
    if (z3d.modelDocumentTokenForId(resident_query.model_id) != z3d.g_model_session_token or
        resident_query.session_token == null or !z3d.faceSessionTokenMatches(resident_query.session_token.?))
    {
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "face-diff request targets a different resident session", false);
    }
    if (resident_query.expected_generation == null or resident_query.expected_generation.? != z3d.g_edit_generation)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_generation", "resident mesh generation changed", true);

    var saved_query = resident_query;
    saved_query.source = .saved;
    saved_query.session_token = null;
    saved_query.expected_generation = null;
    saved_query.geometry_path = parsed.geometry_path;
    saved_query.expected_sha256 = parsed.expected_saved_sha256;

    if (!z3d.g_face_table_worker.isStarted()) z3d.g_face_table_worker.start(io, allocator, 2) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "face-diff worker could not start", false);
    const resident_hash = z3d.residentFacePlaneHashAlloc(
        allocator,
        resident_query.model_id,
        resident_query.session_token.?,
    ) catch |err| return z3d.residentAnalysisErrorAlloc(allocator, err);
    const diff_hash = mesh_face_table_worker.diffPlaneIdentityHashAlloc(allocator, .{
        .model_id = resident_query.model_id,
        .session_token = resident_query.session_token.?,
        .generation = resident_query.expected_generation.?,
        .resident_plane_hash = resident_hash,
        .artifact_sha256 = parsed.expected_saved_sha256,
    }) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-diff plane identity", false),
    };
    if (z3d.g_face_table_worker.cacheView(io, diff_hash)) |cached| switch (cached) {
        .diff => |snapshot| {
            _ = z3d.g_face_table_worker.selectCached(io, diff_hash);
            return mesh_face_diff.queryPageJsonAlloc(
                allocator,
                snapshot,
                mesh_face_diff.queryFromParsed(&parsed),
            ) catch |err| z3d.diffQueryErrorJsonAlloc(allocator, err);
        },
        .success => return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "face-diff cache contains an invalid result kind", false),
        .failure => |failure| return z3d.faceRecoveryErrorJsonAlloc(
            allocator,
            @tagName(mesh_face_table_worker.publicFailureCode(.diff, failure.code)),
            failure.text(),
            false,
        ),
    };
    if (z3d.g_face_table_worker.pendingReceipt(io, diff_hash)) |receipt|
        return mesh_face_table_worker.pendingJsonAlloc(allocator, receipt);

    var bytes = mesh_face_table_package.readSavedQueryFromCwdAlloc(
        io,
        allocator,
        saved_query,
    ) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.InvalidRequest => return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "saved diff geometry is outside the model-package lane", false),
        error.WrongModel => return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "saved diff package belongs to a different model", false),
        else => return z3d.faceRecoveryErrorJsonAlloc(allocator, "unreadable_saved_document", "saved diff geometry could not be read", false),
    };
    defer if (bytes.len > 0) allocator.free(bytes);
    var resident_job = z3d.residentFaceAnalysisJobAlloc(
        allocator,
        resident_query.model_id,
        resident_query.session_token.?,
    ) catch |err| return z3d.residentAnalysisErrorAlloc(allocator, err);
    var resident_job_owned = true;
    defer if (resident_job_owned) resident_job.deinit();
    var prepared = mesh_face_table_worker.PreparedJob.attachSavedDiffAlloc(
        allocator,
        &resident_job,
        &bytes,
        .{
            .source = .saved,
            .model_id = resident_query.model_id,
            .expected_sha256 = parsed.expected_saved_sha256,
        },
        .{},
        .{},
    ) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "face-diff worker input could not be captured", false),
    };
    resident_job_owned = false;
    const prepared_hash = prepared.identityHash();
    if (!std.mem.eql(u8, &prepared_hash, &diff_hash)) {
        prepared.deinit();
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "face-diff identity changed during owner capture", false);
    }
    return switch (z3d.g_face_table_worker.submitOwned(io, prepared)) {
        .queued => |receipt| mesh_face_table_worker.pendingJsonAlloc(allocator, receipt),
        .stopped => z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "face-diff worker stopped", false),
    };
}

pub fn meshFaceTableJsonAlloc(io: std.Io, allocator: std.mem.Allocator, request_json: []const u8) ![]u8 {
    if (z3d.faceRequestIsDiff(allocator, request_json))
        return z3d.meshFaceDiffJsonAlloc(io, allocator, request_json);
    var parsed = mesh_face_table.parseQueryAlloc(allocator, request_json) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-table v1 request", false);
    defer parsed.deinit();
    const query = parsed.query;
    if (query.source == .saved)
        return mesh_face_table_package.inspectSavedFromCwdAlloc(io, allocator, request_json);
    if (query.source == .preview) {
        const token = query.preview_token orelse
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "preview face table requires previewToken", false);
        const sha = query.expected_sha256 orelse
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "preview face table requires expectedSha256", false);
        const specimen = z3d.g_historical_preview.activeFor(token, query.model_id, sha) catch |err|
            return z3d.faceRecoveryErrorJsonAlloc(allocator, switch (err) {
                error.PreviewWrongModel => "wrong_model",
                error.PreviewHashMismatch => "hash_mismatch",
                else => "released_capability",
            }, @errorName(err), false);
        return specimen.analysis.requestJsonAlloc(allocator, request_json);
    }
    if (query.source != .resident)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "unknown face-table plane", false);
    if (!z3d.modelSessionResident())
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "no_resident_session", "no resident model document", false);
    if (z3d.modelDocumentTokenForId(query.model_id) != z3d.g_model_session_token or
        query.session_token == null or !z3d.faceSessionTokenMatches(query.session_token.?))
    {
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "face-table request targets a different resident session", false);
    }
    if (query.expected_generation == null or query.expected_generation.? != z3d.g_edit_generation)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_generation", "resident mesh generation changed", true);
    const lookup = try z3d.residentFaceAnalysisLookup(io, allocator, query.model_id, query.session_token.?);
    const analysis = switch (lookup) {
        .snapshot => |snapshot| snapshot,
        .response => |response| return response,
    };
    return mesh_face_table.queryPageAlloc(allocator, analysis, query) catch |err| switch (err) {
        error.InvalidRequest => z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-table query", false),
        error.WrongModel => z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "face-table identity changed", false),
        error.StaleGeneration => z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_generation", "resident mesh generation changed", true),
        error.AuditUnavailable => z3d.faceRecoveryErrorJsonAlloc(allocator, "audit_unavailable", "requested audit facts were not computed", false),
        error.StaleCursor => z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_cursor", "face-table cursor belongs to another plane or query", false),
        error.AddressNotInQuery => z3d.faceRecoveryErrorJsonAlloc(allocator, "address_not_in_query", "face address is not present in this query", false),
        else => |unhandled| return unhandled,
    };
}

/// Main-thread completion drain. At most one compact event is returned per
/// call; full analysis snapshots remain owned by the resident/cold workers.
pub fn meshFaceAnalysisReadyJsonAlloc(
    io: std.Io,
    allocator: std.mem.Allocator,
) !?[]u8 {
    if (z3d.g_face_table_worker.isStarted()) {
        if (try z3d.g_face_table_worker.takeReadyEventJsonAlloc(io, allocator)) |event| return event;
    }
    return mesh_face_table_package.takeReadyEventJsonAlloc(io, allocator);
}

pub fn meshFaceAnalysisStop(io: std.Io) void {
    z3d.g_face_table_worker.stop(io);
    mesh_face_table_package.stopWorker(io);
}

