}

/// Resolve a durable/local authored-face address, or one stored build issue, to
/// the resident triangle selection and optionally frame it. All identity and
/// membership validation completes before the live selection changes.
pub fn meshFaceSelectJsonAlloc(io: std.Io, allocator: std.mem.Allocator, request_json: []const u8) ![]u8 {
    var parsed = std.json.parseFromSlice(z3d.FaceSelectRequestV1, allocator, request_json, .{}) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-select v1 request", false);
    defer parsed.deinit();
    const request = parsed.value;
    if (request.version != 1 or request.modelId.len == 0)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-select v1 request", false);
    const plane_kind = z3d.facePlaneKind(request.plane) orelse
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-select plane", false);
    if (plane_kind == .preview) {
        if (!std.mem.eql(u8, request.target.kind, "face") or request.target.address == null or
            request.target.objectId != null or request.target.sourceGroup != null)
        {
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "preview selection requires one face address", false);
        }
        const address = z3d.faceAddressView(request.target.address.?) orelse
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid preview face address", false);
        const token = request.plane.previewToken.?;
        const sha = request.plane.expectedSha256.?;
        const specimen = z3d.g_historical_preview.activeFor(token, request.modelId, sha) catch |err|
            return z3d.faceRecoveryErrorJsonAlloc(allocator, switch (err) {
                error.PreviewWrongModel => "wrong_model",
                error.PreviewHashMismatch => "hash_mismatch",
                else => "released_capability",
            }, @errorName(err), false);
        const selected = specimen.selectAddress(address, request.additive) catch |err|
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "address_not_in_query", @errorName(err), false);
        if (request.frame) z3d.orbitFrame(specimen.center, specimen.radius);
        return std.json.Stringify.valueAlloc(allocator, .{
            .ok = true,
            .version = 1,
            .plane = .{
                .source = "preview",
                .previewToken = token,
                .sha256 = &specimen.sha256,
            },
            .target = request.target,
            .selectedTriangles = selected,
        }, .{});
    }
    if (z3d.g_historical_preview.blocksResidentMutation())
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "historical preview selection must target the preview plane", false);
    if (!z3d.modelSessionResident())
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "no_resident_session", "no resident model document", false);
    if (z3d.modelDocumentTokenForId(request.modelId) != z3d.g_model_session_token or
        !z3d.faceSessionTokenMatches(request.plane.sessionToken.?))
    {
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "face selection targets a different resident session", false);
    }
    if (request.plane.expectedGeneration.? != z3d.g_edit_generation)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_generation", "resident mesh generation changed", true);
    if (z3d.g_paint_session)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "face selection is unavailable during a paint stroke", false);

    const face_target = std.mem.eql(u8, request.target.kind, "face");
    const issue_target = std.mem.eql(u8, request.target.kind, "build_issue");
    if (!face_target and !issue_target)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "unknown face selection target", false);
    var address: ?mesh_face_table.AddressView = null;
    if (face_target) {
        if (request.target.objectId != null or request.target.sourceGroup != null)
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "face target fields do not match its kind", false);
        address = z3d.faceAddressView(request.target.address orelse
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "face target requires an address", false)) orelse
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face address", false);
    } else {
        if (request.target.address != null or request.target.objectId == null or
            request.target.objectId.?.len == 0 or request.target.sourceGroup == null)
        {
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "build-issue target fields do not match its kind", false);
        }
    }

    const lookup = try z3d.residentFaceAnalysisLookup(io, allocator, request.modelId, request.plane.sessionToken.?);
    const analysis = switch (lookup) {
        .snapshot => |snapshot| snapshot,
        .response => |response| return response,
    };

    const triangle_count: usize = @intCast(z3d.g_edit_count / 3);
    if (triangle_count == 0 or model_paint.faceCount() != triangle_count)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "resident selection topology does not match face analysis", false);
    const selection_mask = try allocator.alloc(bool, triangle_count);
    defer allocator.free(selection_mask);
    @memset(selection_mask, false);
    var target_triangle_count: u32 = 0;

    if (face_target) {
        const row_index = analysis.findAddress(address.?) orelse
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "address_not_in_query", "face address is not present in the resident analysis", false);
        const row = &analysis.rows.items[row_index];
        for (row.triangle_ids) |triangle| {
            if (triangle >= selection_mask.len)
                return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "face address resolved outside resident selection topology", false);
            if (!selection_mask[triangle]) {
                selection_mask[triangle] = true;
                target_triangle_count += 1;
            }
        }
        if (target_triangle_count == 0 or target_triangle_count != row.triangle_ids.len)
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "face address did not resolve exact triangle membership", false);
    } else {
        const object_id = request.target.objectId.?;
        const source_group = request.target.sourceGroup.?;
        var issue: ?*const mesh_face_table.FaceBuildIssue = null;
        for (analysis.build_issues.items) |*candidate| {
            if (candidate.source_group != source_group or !std.mem.eql(u8, candidate.object_id, object_id)) continue;
            if (issue != null)
                return z3d.faceRecoveryErrorJsonAlloc(allocator, "address_not_in_query", "build-issue target is ambiguous", false);
            issue = candidate;
        }
        const resolved_issue = issue orelse
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "address_not_in_query", "build-issue target is not present in the resident analysis", false);
        for (resolved_issue.source_triangles) |triangle| {
            if (triangle >= selection_mask.len)
                return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "build issue resolved outside resident selection topology", false);
            if (!selection_mask[triangle]) {
                selection_mask[triangle] = true;
                target_triangle_count += 1;
            }
        }
        if (target_triangle_count == 0 or target_triangle_count != resolved_issue.source_triangles.len)
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "build issue did not resolve exact source-triangle membership", false);
    }

    if (request.additive) {
        for (selection_mask, 0..) |*selected, triangle| {
            selected.* = selected.* or mesh_edit.faceSelectedPub(@intCast(triangle));
        }
    }
    var selected_triangles: u32 = 0;
    for (selection_mask) |selected| selected_triangles += @intFromBool(selected);
    if (mesh_edit.selectFacesByTriangleMask(selection_mask) == 0)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "internal_error", "resident face selection could not be applied", false);
    if (request.frame) _ = z3d.orbitFrameCurrent(true);

    if (face_target) return z3d.faceSelectFaceReceiptJsonAlloc(allocator, request, address.?, selected_triangles);
    return z3d.faceSelectBuildIssueReceiptJsonAlloc(
        allocator,
        request,
        request.target.objectId.?,
        request.target.sourceGroup.?,
        selected_triangles,
    );
}

/// Return the page cursor and row offset containing an authored face under the
/// requested native sort/filter. `seekAddressAlloc` remains the sole owner of
/// sort order and cursor construction.
pub fn meshFaceSeekJsonAlloc(io: std.Io, allocator: std.mem.Allocator, request_json: []const u8) ![]u8 {
    var parsed = std.json.parseFromSlice(z3d.FaceSeekRequestV1, allocator, request_json, .{}) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-seek v1 request", false);
    defer parsed.deinit();
    const request = parsed.value;
    if (request.version != 1 or request.modelId.len == 0)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-seek v1 request", false);
    const plane_kind = z3d.facePlaneKind(request.plane) orelse
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-seek plane", false);
    const address = z3d.faceAddressView(request.address) orelse
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face address", false);

    if (plane_kind == .preview) {
        const token = request.plane.previewToken.?;
        const sha = request.plane.expectedSha256.?;
        const specimen = z3d.g_historical_preview.activeFor(token, request.modelId, sha) catch |err|
            return z3d.faceRecoveryErrorJsonAlloc(allocator, switch (err) {
                error.PreviewWrongModel => "wrong_model",
                error.PreviewHashMismatch => "hash_mismatch",
                else => "released_capability",
            }, @errorName(err), false);
        const canonical_query_json = try std.json.Stringify.valueAlloc(allocator, .{
            .version = request.version,
            .modelId = request.modelId,
            .source = "preview",
            .previewToken = token,
            .expectedSha256 = sha,
            .sort = request.sort,
            .filters = request.filters,
            .limit = request.limit,
        }, .{});
        defer allocator.free(canonical_query_json);
        var parsed_query = mesh_face_table.parseQueryAlloc(allocator, canonical_query_json) catch
            return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid preview face-seek query", false);
        defer parsed_query.deinit();
        var receipt = mesh_face_table.seekAddressAlloc(
            allocator,
            &specimen.analysis.snapshot,
            parsed_query.query,
            address,
        ) catch |err| return z3d.faceRecoveryErrorJsonAlloc(allocator, "address_not_in_query", @errorName(err), false);
        defer receipt.deinit();
        return std.json.Stringify.valueAlloc(allocator, .{
            .ok = true,
            .version = 1,
            .cursor = @as(?[]const u8, receipt.cursor),
            .rowOffset = receipt.row_offset,
        }, .{});
    }

    const canonical_query_json = try std.json.Stringify.valueAlloc(allocator, .{
        .version = request.version,
        .modelId = request.modelId,
        .source = "resident",
        .sessionToken = request.plane.sessionToken.?,
        .expectedGeneration = request.plane.expectedGeneration.?,
        .sort = request.sort,
        .filters = request.filters,
        .limit = request.limit,
    }, .{});
    defer allocator.free(canonical_query_json);
    var parsed_query = mesh_face_table.parseQueryAlloc(allocator, canonical_query_json) catch
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-seek sort, filter, or limit", false);
    defer parsed_query.deinit();
    const query = parsed_query.query;

    if (!z3d.modelSessionResident())
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "no_resident_session", "no resident model document", false);
    if (z3d.modelDocumentTokenForId(query.model_id) != z3d.g_model_session_token or
        query.session_token == null or !z3d.faceSessionTokenMatches(query.session_token.?))
    {
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "face seek targets a different resident session", false);
    }
    if (query.expected_generation == null or query.expected_generation.? != z3d.g_edit_generation)
        return z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_generation", "resident mesh generation changed", true);

    const lookup = try z3d.residentFaceAnalysisLookup(io, allocator, query.model_id, query.session_token.?);
    const analysis = switch (lookup) {
        .snapshot => |snapshot| snapshot,
        .response => |response| return response,
    };
    var receipt = mesh_face_table.seekAddressAlloc(allocator, analysis, query, address) catch |err| switch (err) {
        error.InvalidRequest => return z3d.faceRecoveryErrorJsonAlloc(allocator, "invalid_request", "invalid face-seek query", false),
        error.WrongModel => return z3d.faceRecoveryErrorJsonAlloc(allocator, "wrong_model", "face-seek identity changed", false),
        error.StaleGeneration => return z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_generation", "resident mesh generation changed", true),
        error.AuditUnavailable => return z3d.faceRecoveryErrorJsonAlloc(allocator, "audit_unavailable", "requested audit facts were not computed", false),
        error.StaleCursor => return z3d.faceRecoveryErrorJsonAlloc(allocator, "stale_cursor", "face-seek cursor input is invalid", false),
        error.AddressNotInQuery => return z3d.faceRecoveryErrorJsonAlloc(allocator, "address_not_in_query", "face address is excluded from this query", false),
        else => |unhandled| return unhandled,
    };
    defer receipt.deinit();
    return std.json.Stringify.valueAlloc(allocator, .{
        .ok = true,
        .version = 1,
        .cursor = @as(?[]const u8, receipt.cursor),
        .rowOffset = receipt.row_offset,
    }, .{});
}

/// True when the ACTIVE session already holds a resident edit mesh — the cart's
/// "was this document parked here before?" probe (req_3850 slice 2).
pub fn modelSessionResident() bool {
    return z3d.g_edit_count > 0;
}

pub fn findModelSession(token: u32) ?*z3d.ModelSession {
    for (z3d.g_model_sessions.items) |session| {
        if (session.token == token) return session;
    }
    return null;
}

pub fn modelSessionRecord(token: u32) ?*z3d.ModelSession {
    if (z3d.findModelSession(token)) |session| return session;
    const session = z3d.jalloc.create(z3d.ModelSession) catch return null;
    session.* = .{ .token = token };
    z3d.g_model_sessions.append(z3d.jalloc, session) catch {
        z3d.jalloc.destroy(session);
        return null;
    };
    return session;
}

/// Park the active document's native session and restore (or freshly create)
/// the session keyed by `token`. Pointer-copy swaps — no deep copies, no frees.
/// A token seen before restores its parked mesh, journal, selection, paint and
/// semantics exactly as parked (reopening a closed document reclaims its
/// session). An unseen token starts from the modules' boot state; the caller
/// then loads the document into it through the normal load path.
pub fn modelSessionSelect(token: u32) bool {
    if (token == z3d.g_model_session_token) return true;
    if (z3d.g_historical_preview.blocksResidentMutation()) return false;
    // A retained restore/field transaction owns this exact resident session.
    // Parking it would turn that receipt into authority over another document.
    if (z3d.g_model_write_leases.owner() != null) return false;
    z3d.g_face_table_worker.invalidateIdentity();
    const current = z3d.modelSessionRecord(z3d.g_model_session_token) orelse return false;
    mesh_edit.sessionSave(&current.edit);
    model_source.sessionSave(&current.source);
    model_paint.sessionSave(&current.paint);
    z3d.docStateSave(&current.local);
    if (z3d.findModelSession(token)) |target| {
        mesh_edit.sessionLoad(&target.edit);
        model_source.sessionLoad(&target.source);
        model_paint.sessionLoad(&target.paint);
        z3d.docStateLoad(&target.local);
    } else {
        if (z3d.modelSessionRecord(token) == null) return false; // allocation failed
        mesh_edit.sessionReset();
        model_source.sessionReset();
        model_paint.sessionReset();
        z3d.docStateReset();
    }
    z3d.g_model_session_token = token;
    z3d.publishUvZoneMask();
    return true;
}
